const input = $input.first().json;
const headers = input.headers ?? {};
const token = Object.entries(headers).find(([name]) => name.toLowerCase() === 'x-n8n-webhook-token')?.[1];
const expected = $env.N8N_WEBHOOK_TOKEN;
if (!expected || !token || token !== expected) {
  throw new Error('Unauthorized energy alert webhook request');
}

const payload = input.body ?? input;
const alert = payload.alerte;
const organization = payload.organisation;
const recipients = organization?.emails_admin;
if (!alert?.id || !alert?.titre || !alert?.message || !organization?.nom || !Array.isArray(recipients) || recipients.length === 0) {
  throw new Error('Invalid energy alert notification payload');
}
if (recipients.some((email) => typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))) {
  throw new Error('Invalid administrator email address in energy alert payload');
}

const subject = `[EcoScan] ${alert.titre} - ${organization.nom}`;
const text = [
  alert.message,
  '',
  `Niveau : ${alert.severite ?? 'INFORMATION'}`,
  `Type : ${alert.type ?? 'ALERTE_ENERGETIQUE'}`,
  `Organisation : ${organization.nom}`,
  `Référence : ${alert.id}`,
  '',
  `Contexte : ${JSON.stringify(alert.contexte ?? {})}`
].join('\n');
return [{ json: { recipients, subject, text } }];
